#!/usr/bin/env bash
set -u
echo "== 解包导航修复文件 =="
mkdir -p /tmp/xm-nav && rm -rf /tmp/xm-nav/site && mkdir -p /tmp/xm-nav/site
echo '' | base64 -d > /tmp/xm-nav/u.tgz
tar -xzf /tmp/xm-nav/u.tgz -C /tmp/xm-nav/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-nav/site/. /var/www/xinmo-site/
echo "== 校验 =="
ls -l /var/www/xinmo-site/assets/js/nav-toggle.js
grep -c 'nav-toggle' /var/www/xinmo-site/search.html
grep -c 'nav-toggle' /var/www/xinmo-site/profile.html
grep -c 'nav-toggle' /var/www/xinmo-site/certificates.html
echo "== DONE =="
